"""Score Kilo/OpenCode sqlite sessions against Work-gold relations. No bodies."""

from __future__ import annotations

import json
import sqlite3
import statistics
from collections import Counter
from pathlib import Path

WRITE = {"edit", "write", "patch"}
LOOK = {
    "read",
    "grep",
    "glob",
    "webfetch",
    "websearch",
    "semantic_search",
    "kilo_local_recall",
    "skill",
}
LOOKISH = LOOK | {"bash"}
DECOMPOSE = {"task", "todowrite", "agent_manager"}
RELATIONS = (
    ("R1", "r1_look_first"),
    ("R2", "r2_no_write"),
    ("R3", "r3_read_first"),
    ("R4", "r4_no_todowrite"),
    ("R5", "r5_no_write_after_look_run"),
    ("R6", "r6_decompose_not_first"),
)


def fail_mask(s: dict) -> str:
    failed = [name for name, key in RELATIONS if not s.get(key)]
    return "+".join(failed) if failed else "none"


WORK_MAP = {
    "exec": "read",
    "js": "read",
    "wait": "bash",
    "shell_command": "bash",
    "apply_patch": "edit",
    "update_plan": "todowrite",
    "send_message": "task",
    "spawn_agent": "task",
    "wait_agent": "task",
    "list_agents": "task",
    "followup_task": "task",
    "create_thread": "task",
    "multi_agent_v1": "task",
    "interrupt_agent": "task",
}


def map_work_seq(seq: list[str]) -> list[str]:
    """Map Codex Work tool names onto the Kilo/OpenCode scorer alphabet. No bodies."""
    out: list[str] = []
    for t in seq:
        m = WORK_MAP.get(t)
        if m:
            out.append(m)
    return out


def _first_index(seq: list[str], names: set[str]) -> int | None:
    for i, x in enumerate(seq):
        if x in names:
            return i
    return None


def start_look_burst(seq: list[str]) -> int:
    n = 0
    for x in seq:
        if x in LOOKISH:
            n += 1
        else:
            break
    return n


def write_after_look_run(seq: list[str]) -> bool:
    """Work: apply_patch after an exec-run is 0. Look-run then edit fails R5."""
    n = 0
    for x in seq:
        if x in LOOKISH:
            n += 1
            continue
        if n and x in WRITE:
            return True
        n = 0
    return False


def _agents(db: Path) -> dict[str, str]:
    try:
        con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
        rows = {sid: (agent or "") for sid, agent in con.execute("SELECT id, agent FROM session")}
        con.close()
        return rows
    except sqlite3.Error:
        return {}


